    await after({ toolName: "TaskManage", toolCallId: "create-result", input: { operations: [{ key: "work", op: "create", subject: "Do work" }] }, result: { status: "succeeded", results: [{ key: "work", op: "create", status: "succeeded", data: { task: { id: "1" } } }] } }, {});
